import { normalizeOrcid,preferredSummary,dedupeWorks,doiOf,orcidToCsl,mergeCsl,issuesFor,yearOf } from './vendor/core.js';
import {bibliography,parseBibtex} from './vendor/formatter.js';
let resources;
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function json(url,signal){const r=await fetch(url,{headers:{Accept:'application/json'},signal:AbortSignal.any([signal,AbortSignal.timeout(25000)])});if(!r.ok)throw new Error(r.status===404?'No public record was found.':r.status===429||r.status===503?'The data service is busy. Please try again shortly.':`Data service error (${r.status}).`);return r.json();}
async function pool(items,work,signal){let next=0;await Promise.all(Array.from({length:Math.min(3,items.length)},async()=>{while(next<items.length){signal.throwIfAborted();const i=next++;await work(items[i],i);await delay(300);}}));}
export async function fetchDoi(doi,signal){const clean=String(doi).trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').replace(/^doi:\s*/i,'').toLowerCase();if(!/^10\.\d{4,9}\/\S+$/.test(clean))throw new Error('Enter a DOI beginning with 10., or a doi.org link.');const item=await json(`https://api.crossref.org/works/${encodeURIComponent(clean)}/transform/application/vnd.citationstyles.csl+json`,signal);if(!item.title||String(item.DOI??'').toLowerCase()!==clean)throw new Error('The DOI metadata did not match.');return mergeCsl({id:crypto.randomUUID(),type:'article',DOI:clean},item);}
export async function importOrcid(input,signal,progress){const id=normalizeOrcid(input),root=`https://pub.orcid.org/v3.0/${id}`;progress('Finding public works…');const works=await json(root+'/works',signal);const summaries=dedupeWorks((works.group??[]).map(preferredSummary).filter(Boolean));const records=new Array(summaries.length);let count=0;await pool(summaries,async(s,i)=>{let w=s,warning='';try{w=await json(root+'/work/'+s['put-code'],signal);}catch(e){if(signal.aborted)throw e;warning='Full ORCID record unavailable; summary used';}records[i]={item:orcidToCsl(w),source:'ORCID',warnings:warning?[warning]:[]};progress(`Reading publication details: ${++count} of ${summaries.length}`);},signal);count=0;const withDoi=records.filter(r=>r.item.DOI);await pool(withDoi,async r=>{try{const meta=await fetchDoi(r.item.DOI,signal);r.item=mergeCsl(r.item,meta);r.source='ORCID + Crossref';}catch(e){if(signal.aborted)throw e;r.warnings.push('DOI metadata unavailable; check the ORCID reference');}progress(`Completing DOI details: ${++count} of ${withDoi.length}`);},signal);return records;}
export function importBib(text){const {items,duplicates}=parseBibtex(text);return {records:items.map(item=>({item,source:'BibTeX file',warnings:[]})),duplicates};}
export async function formatRecords(records,matchRanking){resources??=Promise.all(['apa.csl','locales-en-US.xml'].map(async path=>{const r=await fetch('./vendor/'+path);if(!r.ok)throw new Error('The citation formatting resources could not be loaded.');return r.text();}));const [style,locale]=await resources;const unique=records.map((r,i)=>({...r,item:{...r.item,id:'candidate_'+i}}));const refs=unique.length?bibliography(unique.map(r=>r.item),style,locale):[];const byId=new Map(refs.map(r=>[r.id,r.html]));return unique.map(r=>{const d=new DOMParser().parseFromString(byId.get(r.item.id)??'','text/html');const journal=r.item['container-title']??'';const issns=Array.isArray(r.item.ISSN)?r.item.ISSN:r.item.ISSN?[r.item.ISSN]:[];return {id:crypto.randomUUID(),type:r.item.type??'article',title:String(r.item.title??''),apa:d.body.textContent.trim(),journal,year:String(yearOf(r.item)),doi:r.item.DOI??'',issns,vreUrl:'',source:r.source,issues:[...issuesFor(r.item),...(r.warnings??[])],...matchRanking(journal,issns)};});}
